struct parsec_lifo_opaque_s
    data::NTuple{48, UInt8}
end

function Base.getproperty(x::Ptr{parsec_lifo_opaque_s}, f::Symbol)
    f === :super && return Ptr{parsec_object_t}(x + 0)
    f === :alignment && return Ptr{UInt8}(x + 16)
    f === :int128_private && return Ptr{Int128}(x + 32)
    f === :lifo_private && return Ptr{NTuple{16, Cchar}}(x + 32)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_lifo_opaque_s, f::Symbol)
    r = Ref{parsec_lifo_opaque_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_lifo_opaque_s}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_lifo_opaque_s}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_lifo_opaque_s, private::Bool = false)
    (:super, :alignment, :int128_private, :lifo_private, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

