struct parsec_arena_s
    data::NTuple{112, UInt8}
end

function Base.getproperty(x::Ptr{parsec_arena_s}, f::Symbol)
    f === :super && return Ptr{parsec_object_t}(x + 0)
    f === :area_lifo && return Ptr{parsec_lifo_t}(x + 16)
    f === :alignment && return Ptr{Csize_t}(x + 64)
    f === :elem_size && return Ptr{Csize_t}(x + 72)
    f === :used && return Ptr{Int32}(x + 80)
    f === :max_used && return Ptr{Int32}(x + 84)
    f === :released && return Ptr{Int32}(x + 88)
    f === :max_released && return Ptr{Int32}(x + 92)
    f === :data_malloc && return Ptr{parsec_data_allocate_t}(x + 96)
    f === :data_free && return Ptr{parsec_data_free_t}(x + 104)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_arena_s, f::Symbol)
    r = Ref{parsec_arena_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_arena_s}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_arena_s}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_arena_s, private::Bool = false)
    (:super, :area_lifo, :alignment, :elem_size, :used, :max_used, :released, :max_released, :data_malloc, :data_free, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

