function Base.getproperty(x::Ptr{parsec_barrier_t}, f::Symbol)
    f === :count && return Ptr{Cint}(x + 0)
    f === :curcount && return Ptr{Cint}(x + 4)
    f === :generation && return Ptr{Cint}(x + 8)
    f === :mutex && return Ptr{pthread_mutex_t}(x + 16)
    f === :cond && return Ptr{pthread_cond_t}(x + 56)
    return getfield(x, f)
end

