function Base.getproperty(x::Ptr{parsec_context_s}, f::Symbol)
    f === :__parsec_internal_finalization_in_progress && return Ptr{Int32}(x + 0)
    f === :__parsec_internal_finalization_counter && return Ptr{Int32}(x + 4)
    f === :active_taskpools && return Ptr{Int32}(x + 8)
    f === :flags && return Ptr{Int32}(x + 12)
    f === :comm_ctx && return Ptr{Cptrdiff_t}(x + 16)
    f === :nb_nodes && return Ptr{Int32}(x + 24)
    f === :my_rank && return Ptr{Int32}(x + 28)
    f === :barrier && return Ptr{parsec_barrier_t}(x + 32)
    f === :remote_dep_fw_mask_sizeof && return Ptr{Csize_t}(x + 136)
    f === :pthreads && return Ptr{Ptr{pthread_t}}(x + 144)
    f === :nb_vp && return Ptr{Int32}(x + 152)
    f === :taskpool_list && return Ptr{Ptr{parsec_list_t}}(x + 160)
    f === :dtd_arena_datatypes_hash_table && return Ptr{parsec_hash_table_t}(x + 168)
    f === :dtd_arena_datatypes_next_id && return Ptr{Cint}(x + 264)
    f === :comm_th_core && return Ptr{Cint}(x + 268)
    f === :cpuset_allowed_mask && return Ptr{hwloc_cpuset_t}(x + 272)
    f === :cpuset_free_mask && return Ptr{hwloc_cpuset_t}(x + 280)
    f === :virtual_processes && return Ptr{NTuple{1, Ptr{parsec_vp_s}}}(x + 288)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_context_s, f::Symbol)
    r = Ref{parsec_context_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_context_s}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_context_s}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_context_s, private::Bool = false)
    (:__parsec_internal_finalization_in_progress, :__parsec_internal_finalization_counter, :active_taskpools, :flags, :comm_ctx, :nb_nodes, :my_rank, :barrier, :remote_dep_fw_mask_sizeof, :pthreads, :nb_vp, :taskpool_list, :dtd_arena_datatypes_hash_table, :dtd_arena_datatypes_next_id, :comm_th_core, :cpuset_allowed_mask, :cpuset_free_mask, :virtual_processes, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

