struct parsec_dependencies_union_t
    data::NTuple{8, UInt8}
end

function Base.getproperty(x::Ptr{parsec_dependencies_union_t}, f::Symbol)
    f === :dependencies && return Ptr{NTuple{1, parsec_dependency_t}}(x + 0)
    f === :next && return Ptr{NTuple{1, Ptr{parsec_dependencies_t}}}(x + 0)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_dependencies_union_t, f::Symbol)
    r = Ref{parsec_dependencies_union_t}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_dependencies_union_t}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_dependencies_union_t}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_dependencies_union_t, private::Bool = false)
    (:dependencies, :next, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

struct parsec_dependencies_s
    data::NTuple{24, UInt8}
end

function Base.getproperty(x::Ptr{parsec_dependencies_s}, f::Symbol)
    f === :flags && return Ptr{Cint}(x + 0)
    f === :min && return Ptr{Cint}(x + 4)
    f === :max && return Ptr{Cint}(x + 8)
    f === :u && return Ptr{parsec_dependencies_union_t}(x + 16)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_dependencies_s, f::Symbol)
    r = Ref{parsec_dependencies_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_dependencies_s}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_dependencies_s}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_dependencies_s, private::Bool = false)
    (:flags, :min, :max, :u, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

