struct var"##Ctag#419"
    data::NTuple{8, UInt8}
end

function Base.getproperty(x::Ptr{var"##Ctag#419"}, f::Symbol)
    f === :inline_func_int32 && return Ptr{parsec_expr_op_int32_inline_func_t}(x + 0)
    f === :inline_func_int64 && return Ptr{parsec_expr_op_int64_inline_func_t}(x + 0)
    f === :inline_func_float && return Ptr{parsec_expr_op_float_inline_func_t}(x + 0)
    f === :inline_func_double && return Ptr{parsec_expr_op_double_inline_func_t}(x + 0)
    return getfield(x, f)
end

function Base.getproperty(x::var"##Ctag#419", f::Symbol)
    r = Ref{var"##Ctag#419"}(x)
    ptr = Base.unsafe_convert(Ptr{var"##Ctag#419"}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{var"##Ctag#419"}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::var"##Ctag#419", private::Bool = false)
    (:inline_func_int32, :inline_func_int64, :inline_func_float, :inline_func_double, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

