struct parsec_gpu_task_s
    data::NTuple{744, UInt8}
end

function Base.getproperty(x::Ptr{parsec_gpu_task_s}, f::Symbol)
    f === :list_item && return Ptr{parsec_list_item_t}(x + 0)
    f === :task_type && return Ptr{UInt16}(x + 40)
    f === :pushout && return Ptr{UInt16}(x + 42)
    f === :last_status && return Ptr{Int32}(x + 44)
    f === :submit && return Ptr{parsec_advance_task_function_t}(x + 48)
    f === :complete_stage && return Ptr{parsec_complete_stage_function_t}(x + 56)
    f === :stage_in && return Ptr{Ptr{parsec_stage_in_function_t}}(x + 64)
    f === :stage_out && return Ptr{Ptr{parsec_stage_out_function_t}}(x + 72)
    f === :release_device_task && return Ptr{parsec_release_device_task_function_t}(x + 80)
    f === :ec && return Ptr{Ptr{parsec_task_t}}(x + 88)
    f === :last_data_check_epoch && return Ptr{UInt64}(x + 96)
    f === :flow && return Ptr{NTuple{20, Ptr{parsec_flow_t}}}(x + 104)
    f === :flow_nb_elts && return Ptr{NTuple{20, Csize_t}}(x + 264)
    f === :flow_dc && return Ptr{NTuple{20, Ptr{parsec_data_collection_t}}}(x + 424)
    f === :sources && return Ptr{NTuple{20, Ptr{parsec_data_copy_t}}}(x + 584)
    f === :copy && return Ptr{Ptr{parsec_data_copy_t}}(x + 88)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_gpu_task_s, f::Symbol)
    r = Ref{parsec_gpu_task_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_gpu_task_s}, r)
    fptr = getproperty(ptr, f)
    GC.@preserve r unsafe_load(fptr)
end

function Base.setproperty!(x::Ptr{parsec_gpu_task_s}, f::Symbol, v)
    unsafe_store!(getproperty(x, f), v)
end

function Base.propertynames(x::parsec_gpu_task_s, private::Bool = false)
    (:list_item, :task_type, :pushout, :last_status, :submit, :complete_stage, :stage_in, :stage_out, :release_device_task, :ec, :last_data_check_epoch, :flow, :flow_nb_elts, :flow_dc, :sources, :copy, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

