struct parsec_comm_engine_capabilites_s
    data::NTuple{4, UInt8}
end

function Base.getproperty(x::Ptr{parsec_comm_engine_capabilites_s}, f::Symbol)
    f === :sided && return (Ptr{Cuint}(x + 0), 0, 2)
    f === :supports_noncontiguous_datatype && return (Ptr{Cuint}(x + 0), 2, 1)
    f === :multithreaded && return (Ptr{Cuint}(x + 0), 3, 1)
    return getfield(x, f)
end

function Base.getproperty(x::parsec_comm_engine_capabilites_s, f::Symbol)
    r = Ref{parsec_comm_engine_capabilites_s}(x)
    ptr = Base.unsafe_convert(Ptr{parsec_comm_engine_capabilites_s}, r)
    fptr = getproperty(ptr, f)
    begin
        if fptr isa Ptr
            return GC.@preserve(r, unsafe_load(fptr))
        else
            (baseptr, offset, width) = fptr
            ty = eltype(baseptr)
            baseptr32 = convert(Ptr{UInt32}, baseptr)
            u64 = GC.@preserve(r, unsafe_load(baseptr32))
            if offset + width > 32
                u64 |= GC.@preserve(r, unsafe_load(baseptr32 + 4)) << 32
            end
            u64 = u64 >> offset & (1 << width - 1)
            return u64 % ty
        end
    end
end

function Base.setproperty!(x::Ptr{parsec_comm_engine_capabilites_s}, f::Symbol, v)
    fptr = getproperty(x, f)
    if fptr isa Ptr
        unsafe_store!(getproperty(x, f), v)
    else
        (baseptr, offset, width) = fptr
        baseptr32 = convert(Ptr{UInt32}, baseptr)
        u64 = unsafe_load(baseptr32)
        straddle = offset + width > 32
        if straddle
            u64 |= unsafe_load(baseptr32 + 4) << 32
        end
        mask = 1 << width - 1
        u64 &= ~(mask << offset)
        u64 |= (unsigned(v) & mask) << offset
        unsafe_store!(baseptr32, u64 & typemax(UInt32))
        if straddle
            unsafe_store!(baseptr32 + 4, u64 >> 32)
        end
    end
end

function Base.propertynames(x::parsec_comm_engine_capabilites_s, private::Bool = false)
    (:sided, :supports_noncontiguous_datatype, :multithreaded, if private
            fieldnames(typeof(x))
        else
            ()
        end...)
end

